//! Only canonical paths generated by this producer are accepted, with no aliases.
pub fn id(value: &str, kind: &str) -> Option<u64> {
    let rest = value
        .strip_prefix("/org/gnome/Mutter/ScreenCast/")?
        .strip_prefix(kind)?
        .strip_prefix("/u")?;
    if rest.is_empty()
        || rest.len() > 20
        || rest.starts_with('0')
        || !rest.bytes().all(|b| b.is_ascii_digit())
    {
        return None;
    }
    rest.parse().ok()
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn exact_kind_and_full_nonzero_identity_are_required() {
        assert_eq!(
            id("/org/gnome/Mutter/ScreenCast/Session/u1", "Session"),
            Some(1)
        );
        assert_eq!(
            id(
                "/org/gnome/Mutter/ScreenCast/Stream/u18446744073709551615",
                "Stream"
            ),
            Some(u64::MAX)
        );
        for value in [
            "",
            "/org/gnome/Mutter/ScreenCast/Stream/u1",
            "/org/gnome/Mutter/ScreenCast/Session/u0",
            "/org/gnome/Mutter/ScreenCast/Session/u01",
            "/org/gnome/Mutter/ScreenCast/Session/u+1",
            "/org/gnome/Mutter/ScreenCast/Session/u1/extra",
            "/org/gnome/Mutter/ScreenCast/Session/u18446744073709551616",
        ] {
            assert_eq!(id(value, "Session"), None, "{value}");
        }
    }
}
